// 1. Obtener todas las filas de la hoja Mega
const rows = $input.all();
const megaToken = '1655|Uk2GI2EUH0v8NIcUFjGwLeKLlp14bVmEi2rcGSuJ48ec8236';
const megaApiBase = 'https://megaott.net/api/v1';

const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k.trim())) {
      const v = obj[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
};

// 2. Extraer identificadores / usuarios / IDs
const extractedList = [];
for (let i = 0; i < rows.length; i++) {
  const row = rows[i].json || {};
  const idVal = getField(row, /^(id|sub_id|subscription_id)/i);
  const usuario = getField(row, /^(usuario|username|user)/i);
  const nombre = getField(row, /^(nombre|name|cliente)/i);
  const apellido = getField(row, /^(apellido|last_name)/i);
  const tel = getField(row, /^(tel|phone|cel|movil|whats)/i);
  const email = getField(row, /^(email|correo)/i);
  const vence = getField(row, /^(vence|expire)/i);

  extractedList.push({
    row_index: i + 2,
    id: idVal,
    usuario: usuario,
    nombre: [nombre, apellido].filter(Boolean).join(' '),
    telefono: tel,
    email: email,
    vence: vence,
    original_row: row
  });
}

// 3. Consultar la API de MegaOTT para cada registro con ID
const processedRecords = [];
const allKeysSet = new Set(['sheet_row', 'sheet_usuario', 'sheet_nombre', 'sheet_telefono', 'sheet_email', 'sheet_vence']);

for (let j = 0; j < extractedList.length; j++) {
  const item = extractedList[j];
  let apiData = null;

  if (item.id && /^\d+$/.test(item.id)) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: `${megaApiBase}/subscriptions/${item.id}`,
        headers: {
          'Authorization': `Bearer ${megaToken}`,
          'Accept': 'application/json',
          'User-Agent': 'Mozilla/5.0'
        },
        json: true
      });
      if (res && res.data) {
        apiData = res.data;
      } else if (res && typeof res === 'object') {
        apiData = res;
      }
    } catch (e) {
      // Ignorar 404
    }
  }

  const record = {
    sheet_row: item.row_index,
    sheet_usuario: item.usuario,
    sheet_nombre: item.nombre,
    sheet_telefono: item.telefono,
    sheet_email: item.email,
    sheet_vence: item.vence
  };

  if (apiData) {
    for (const [k, v] of Object.entries(apiData)) {
      allKeysSet.add(k);
      record[k] = (v !== null && typeof v === 'object') ? JSON.stringify(v) : v;
    }
  } else {
    for (const [k, v] of Object.entries(item.original_row)) {
      const cleanK = 'orig_' + k.replace(/\s+/g, '_');
      allKeysSet.add(cleanK);
      record[cleanK] = (v !== null && typeof v === 'object') ? JSON.stringify(v) : v;
    }
  }

  processedRecords.push(record);
}

const headersList = Array.from(allKeysSet);

const sheetValues = [
  headersList,
  ...processedRecords.map(rec => headersList.map(h => rec[h] !== undefined && rec[h] !== null ? String(rec[h]) : ''))
];

return [{
  json: {
    total_records: processedRecords.length,
    total_columns: headersList.length,
    headers: headersList,
    values: sheetValues,
    spreadsheet_id: '1SNRbfgomUgtac58UmIMlH8UzizBXrTDVogxJEt-z9A0',
    sheet_name: 'MegaData'
  }
}];

const summary = $("Procesar y Estructurar MegaData").first().json;
const apiResponse = $input.first().json;

return [{
  json: {
    status: "success",
    message: "MegaData synchronization completed successfully.",
    spreadsheet_id: summary.spreadsheet_id,
    sheet_name: summary.sheet_name,
    total_records_processed: summary.total_records,
    total_columns_generated: summary.total_columns,
    columns_list: summary.headers,
    updated_range: apiResponse.updatedRange || "MegaData!A1",
    updated_rows: apiResponse.updatedRows || summary.total_records + 1,
    updated_columns: apiResponse.updatedColumns || summary.total_columns
  }
}];
